css:
.am { text-align: center; margin-top: 48px; }
.am[hidden] { display: none; }
.am-btn { font-family: var(--font-heading); font-weight: 600; font-size: 14px; letter-spacing: 0.12em; text-transform: uppercase; color: #f4fbff; background: transparent; border: 1px solid rgba(255,255,255,0.25); padding: 14px 34px; border-radius: 6px; cursor: pointer; transition: border-color .25s ease, color .25s ease; }
.am-btn:hover { border-color: #00cdfd; color: #00fbff; }
